if __name__=='__main__':
    keys={f['key'] for k in C for f in k['fields']}
    assert keys<=set(EN),sorted(keys-set(EN))
    data={'version':1,'purpose':'Developer schema semantics, not owner facts, not customer-question aliases','fields':{key:{'description_en':EN[key]} for key in sorted(keys)}}
    p=SYSTEM/'app/knowledge/common/schema_descriptions.json'
    with p.open('x',encoding='utf-8') as f:json.dump(data,f,ensure_ascii=False,indent=2)
    print('English semantic descriptions for '+str(len(keys))+' unique attributes / '+str(sum(len(k['fields']) for k in C))+' slots')
